--
-- Schema and ledger of a usage database written by the RELEASED v4.7.1 binaries
-- (usage schema version 12, data version 1, historical-usage-validation-v1 validated).
-- The upgrade tests load this file instead of synthesising a v4.7.1 shape, so the
-- fresh-versus-upgraded comparison is made against the schema a customer actually has.
--
-- Generated 2026-11-08 with the published asset (gh release download v4.7.1,
-- SHA256SUMS verified, metrum-ai-router --version reports v4.7.1 go1.26.10):
--   metrum-ai-router-migrate --scope=usage --driver=sqlite --db=usage.sqlite --action=apply
--   metrum-ai-router-migrate --scope=usage --driver=sqlite --db=usage.sqlite \
--     --action=resume --job=historical-usage-validation-v1 --checkpoint-ordinal=0
--   sqlite3 usage.sqlite .dump  (schema objects plus the ledger, data-job and checkpoint
--     rows that make the database serving-compatible; request rows are not included)
--
-- A v4.7.1 deployment in file-config mode has no router-config control-plane database, so
-- only the usage scope is captured here; the config scope is exercised with real binaries
-- in the release verification instead.
--
-- Load with: for each statement up to the terminating semicolon, exec it in order.

BEGIN;
CREATE TABLE `authz_policy_audit_events` (`id` integer PRIMARY KEY AUTOINCREMENT,`policy_set_id` text NOT NULL,`actor_subject` text NOT NULL,`action` text NOT NULL,`ts` text NOT NULL,`request_id` text NOT NULL,`safe_summary` text NOT NULL);
CREATE TABLE `authz_policy_rules` (`id` integer PRIMARY KEY AUTOINCREMENT,`policy_set_id` text NOT NULL,`sequence` integer NOT NULL,`ptype` text NOT NULL,`subject_or_role` text NOT NULL,`domain` text NOT NULL,`object` text NOT NULL,`action` text NOT NULL,`effect` text NOT NULL DEFAULT "");
CREATE TABLE `authz_policy_sets` (`id` text,`name` text NOT NULL,`version` integer NOT NULL,`status` text NOT NULL,`created_by` text NOT NULL,`created_at` text NOT NULL,`activated_at` text NOT NULL DEFAULT "",`retired_at` text NOT NULL DEFAULT "",PRIMARY KEY (`id`));
CREATE TABLE `authz_role_links` (`id` integer PRIMARY KEY AUTOINCREMENT,`policy_set_id` text NOT NULL,`sequence` integer NOT NULL,`subject` text NOT NULL,`role` text NOT NULL,`domain` text NOT NULL);
CREATE TABLE `legal_hold_audit_events` (`id` integer PRIMARY KEY AUTOINCREMENT,`hold_id` text NOT NULL,`event_type` text NOT NULL,`data_class` text NOT NULL,`request_id` text NOT NULL DEFAULT "",`start_ts` text NOT NULL DEFAULT "",`end_ts` text NOT NULL DEFAULT "",`previous_active` numeric NOT NULL,`new_active` numeric NOT NULL,`actor` text NOT NULL DEFAULT "",`reason_code` text NOT NULL DEFAULT "",`message` text NOT NULL DEFAULT "",`ts` text NOT NULL);
CREATE TABLE `legal_holds` (`id` integer PRIMARY KEY AUTOINCREMENT,`hold_id` text NOT NULL,`data_class` text NOT NULL,`request_id` text NOT NULL DEFAULT "",`active` numeric NOT NULL,`start_ts` text NOT NULL DEFAULT "",`end_ts` text NOT NULL DEFAULT "",`reason_code` text NOT NULL DEFAULT "",`subject` text NOT NULL DEFAULT "",`created_by` text NOT NULL DEFAULT "",`created_at` text NOT NULL,`released_by` text NOT NULL DEFAULT "",`released_at` text NOT NULL DEFAULT "",`release_reason` text NOT NULL DEFAULT "",`notes` text NOT NULL DEFAULT "");
CREATE TABLE `request_attempts` (`request_id` text,`attempt_index` integer NOT NULL,`ts` text NOT NULL,`provider` text NOT NULL,`model` text NOT NULL,`dialect` text NOT NULL,`endpoint_host` text NOT NULL,`duration_ms` integer NOT NULL,`status_code` integer NOT NULL,`error_class` text NOT NULL,`error_message` text NOT NULL,`retryable` numeric NOT NULL,`timed_out` numeric NOT NULL,`client_canceled` numeric NOT NULL,`selected` numeric NOT NULL,`fallback_reason` text NOT NULL,`request_bytes` integer NOT NULL,`response_bytes` integer NOT NULL,`attempt_timeout_ms` integer NOT NULL,`retry_after_ms` integer NOT NULL DEFAULT 0, `reasoning_tokens` integer,PRIMARY KEY (`request_id`,`attempt_index`));
CREATE TABLE `request_cache_reasons` (`request_id` text,`seq` integer NOT NULL,`status` text NOT NULL,`reason` text NOT NULL,`candidate_index` integer NOT NULL,`provider` text NOT NULL,`model` text NOT NULL,`dialect` text NOT NULL,PRIMARY KEY (`request_id`,`seq`),CONSTRAINT `fk_request_usage_decision_cache_reasons` FOREIGN KEY (`request_id`) REFERENCES `request_usage`(`request_id`) ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE `request_content_audit_events` (`id` integer PRIMARY KEY AUTOINCREMENT,`ts` text NOT NULL,`action` text NOT NULL,`request_id` text NOT NULL,`actor_caller_id` text NOT NULL,`actor_token_id` text NOT NULL,`scope` text NOT NULL,`rows_affected` integer NOT NULL,`reason` text NOT NULL);
CREATE TABLE `request_content_captures` (`id` integer PRIMARY KEY AUTOINCREMENT,`request_id` text NOT NULL,`ts` text NOT NULL,`scope` text NOT NULL,`sequence` integer NOT NULL,`caller_id` text NOT NULL,`token_id` text NOT NULL,`resolved_group` text NOT NULL,`target_provider` text NOT NULL,`target_model` text NOT NULL,`inbound_dialect` text NOT NULL,`target_dialect` text NOT NULL,`content_type` text NOT NULL,`content_text` text NOT NULL,`encryption_nonce` text NOT NULL DEFAULT "",`encryption_kms_key_id` text NOT NULL DEFAULT "",`encrypted` numeric NOT NULL DEFAULT false,`content_bytes` integer NOT NULL,`truncated` numeric NOT NULL,`redacted` numeric NOT NULL,`redaction_count` integer NOT NULL,`images_captured` numeric NOT NULL,`image_count` integer NOT NULL,`source_status` integer NOT NULL,`retention_until` text NOT NULL,`deletion_requested` numeric NOT NULL DEFAULT false);
CREATE TABLE `request_content_headers` (`id` integer PRIMARY KEY AUTOINCREMENT,`capture_id` integer NOT NULL,`request_id` text NOT NULL,`scope` text NOT NULL,`name` text NOT NULL,`value` text NOT NULL,`encryption_nonce` text NOT NULL DEFAULT "",`encryption_kms_key_id` text NOT NULL DEFAULT "",`encrypted` numeric NOT NULL DEFAULT false,`redacted` numeric NOT NULL);
CREATE TABLE `request_decision_shape_features` (`request_id` text,`seq` integer NOT NULL,`feature_name` text NOT NULL,`bool_value` numeric NOT NULL,`int_value` integer NOT NULL,`text_value` text NOT NULL,PRIMARY KEY (`request_id`,`seq`),CONSTRAINT `fk_request_usage_decision_shape_features` FOREIGN KEY (`request_id`) REFERENCES `request_usage`(`request_id`) ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE `request_dynamic_score_terms` (`request_id` text,`seq` integer NOT NULL,`candidate_index` integer NOT NULL,`rank` integer NOT NULL,`provider` text NOT NULL,`model` text NOT NULL,`dialect` text NOT NULL,`term_name` text NOT NULL,`score_name` text NOT NULL DEFAULT "",`weight` real NOT NULL DEFAULT 0,`value` real NOT NULL DEFAULT 0,`contribution` real NOT NULL DEFAULT 0,`final_score` real NOT NULL DEFAULT 0,`value_bucket` text NOT NULL DEFAULT "",`contribution_bucket` text NOT NULL DEFAULT "",`final_score_bucket` text NOT NULL DEFAULT "",`observation_count` integer NOT NULL DEFAULT 0,`selected` numeric NOT NULL DEFAULT false,PRIMARY KEY (`request_id`,`seq`),CONSTRAINT `fk_request_usage_dynamic_score_terms` FOREIGN KEY (`request_id`) REFERENCES `request_usage`(`request_id`) ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE `request_errors` (`request_id` text,`ts` text NOT NULL,`status` integer NOT NULL,`error_type` text NOT NULL,`error_class` text NOT NULL,`error_message` text NOT NULL,`retryable` numeric NOT NULL,`attempts` integer NOT NULL,`provider` text NOT NULL,`model` text NOT NULL,`dialect` text NOT NULL,PRIMARY KEY (`request_id`));
CREATE TABLE `request_fallback_transitions` (`request_id` text,`seq` integer NOT NULL,`attempt_index` integer NOT NULL,`failed_candidate_index` integer NOT NULL,`fallback_candidate_index` integer NOT NULL,`failed_provider` text NOT NULL,`failed_model` text NOT NULL,`failed_dialect` text NOT NULL,`fallback_provider` text NOT NULL,`fallback_model` text NOT NULL,`fallback_dialect` text NOT NULL,`fallback_reason` text NOT NULL,`error_class` text NOT NULL,`retryable` numeric NOT NULL DEFAULT false,`fallback_succeeded` numeric NOT NULL DEFAULT false,PRIMARY KEY (`request_id`,`seq`),CONSTRAINT `fk_request_usage_fallback_transitions` FOREIGN KEY (`request_id`) REFERENCES `request_usage`(`request_id`) ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE `request_policy_executions` (`request_id` text,`seq` integer NOT NULL,`strategy` text NOT NULL,`policy_kind` text NOT NULL,`outcome` text NOT NULL,`duration_ms` integer NOT NULL DEFAULT 0,`eligible_target_count` integer NOT NULL DEFAULT 0,`all_target_count` integer NOT NULL DEFAULT 0,`selected_candidate_index` integer NOT NULL,`fallback_count` integer NOT NULL DEFAULT 0,`class_label` text NOT NULL DEFAULT "",`error_class` text NOT NULL DEFAULT "",`error_message` text NOT NULL DEFAULT "",`terminal_error_type` text NOT NULL DEFAULT "",PRIMARY KEY (`request_id`,`seq`),CONSTRAINT `fk_request_usage_policy_executions` FOREIGN KEY (`request_id`) REFERENCES `request_usage`(`request_id`) ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE `request_routing_decisions` (`request_id` text,`seq` integer NOT NULL,`strategy` text NOT NULL,`selected_candidate_index` integer NOT NULL,`provider` text NOT NULL,`model` text NOT NULL,`dialect` text NOT NULL,`fallback_count` integer NOT NULL,`class_label` text NOT NULL,PRIMARY KEY (`request_id`,`seq`),CONSTRAINT `fk_request_usage_routing_decisions` FOREIGN KEY (`request_id`) REFERENCES `request_usage`(`request_id`) ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE `request_routing_signals` (`request_id` text,`seq` integer NOT NULL,`strategy` text NOT NULL,`signal_name` text NOT NULL,`source` text NOT NULL DEFAULT "",`candidate_index` integer NOT NULL,`bool_value` numeric NOT NULL DEFAULT false,`int_value` integer NOT NULL DEFAULT 0,`float_value` real NOT NULL DEFAULT 0,`text_value` text NOT NULL DEFAULT "",PRIMARY KEY (`request_id`,`seq`),CONSTRAINT `fk_request_usage_routing_signals` FOREIGN KEY (`request_id`) REFERENCES `request_usage`(`request_id`) ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE `request_shapes` (`request_id` text,`ts` text NOT NULL,`inbound_dialect` text NOT NULL,`requested_model` text NOT NULL,`resolved_group` text NOT NULL DEFAULT "",`client` text NOT NULL DEFAULT "",`stream` numeric NOT NULL DEFAULT false,`input_item_count` integer NOT NULL DEFAULT 0,`message_count` integer NOT NULL DEFAULT 0,`system_message_count` integer NOT NULL DEFAULT 0,`developer_message_count` integer NOT NULL DEFAULT 0,`user_message_count` integer NOT NULL DEFAULT 0,`assistant_message_count` integer NOT NULL DEFAULT 0,`tool_result_count` integer NOT NULL DEFAULT 0,`function_call_output_count` integer NOT NULL DEFAULT 0,`tool_count` integer NOT NULL DEFAULT 0,`tool_choice_mode` text NOT NULL DEFAULT "",`parallel_tool_calls_present` numeric NOT NULL DEFAULT false,`response_format_present` numeric NOT NULL DEFAULT false,`structured_output_present` numeric NOT NULL DEFAULT false,`reasoning_present` numeric NOT NULL DEFAULT false,`reasoning_effort_bucket` text NOT NULL DEFAULT "",`reasoning_budget_bucket` text NOT NULL DEFAULT "",`include_present` numeric NOT NULL DEFAULT false,`truncation_present` numeric NOT NULL DEFAULT false,`metadata_present` numeric NOT NULL DEFAULT false,`store_present` numeric NOT NULL DEFAULT false,`previous_response_id_present` numeric NOT NULL DEFAULT false,`image_count` integer NOT NULL DEFAULT 0,`audio_present` numeric NOT NULL DEFAULT false,`video_present` numeric NOT NULL DEFAULT false,`input_text_bytes_bucket` text NOT NULL DEFAULT "",`tool_schema_bytes_bucket` text NOT NULL DEFAULT "",`total_request_bytes_bucket` text NOT NULL DEFAULT "",`estimated_input_tokens_bucket` text NOT NULL DEFAULT "",`requested_output_cap_field` text NOT NULL DEFAULT "",`requested_output_cap_bucket` text NOT NULL DEFAULT "",`tool_schema_fingerprint` text NOT NULL DEFAULT "",`request_shape_fingerprint` text NOT NULL DEFAULT "",PRIMARY KEY (`request_id`));
CREATE TABLE `request_target_candidates` (`request_id` text,`candidate_index` integer NOT NULL,`group_target_index` integer NOT NULL,`provider` text NOT NULL,`model` text NOT NULL,`model_ref` text NOT NULL,`dialect` text NOT NULL,`weight` integer NOT NULL,`tool_only` numeric NOT NULL,`context_tokens` integer NOT NULL DEFAULT 0,`max_estimated_input_tokens` integer NOT NULL DEFAULT 0,`max_requested_output_tokens` integer NOT NULL DEFAULT 0,`max_request_bytes` integer NOT NULL DEFAULT 0,`max_tool_schema_bytes` integer NOT NULL DEFAULT 0,`estimated_total_input_tokens` integer NOT NULL DEFAULT 0,`requested_output_cap_tokens` integer NOT NULL DEFAULT 0,`estimated_total_with_output_cap` integer NOT NULL DEFAULT 0,`request_bytes` integer NOT NULL DEFAULT 0,`tool_schema_bytes` integer NOT NULL DEFAULT 0,`context_headroom_tokens` integer NOT NULL DEFAULT 0,`context_fit` numeric NOT NULL DEFAULT false,`request_bytes_fit` numeric NOT NULL DEFAULT false,`tool_schema_fit` numeric NOT NULL DEFAULT false,`eligibility_decision` text NOT NULL DEFAULT "",`eligibility_reason` text NOT NULL DEFAULT "",`input_image` numeric NOT NULL DEFAULT false,`output_image` numeric NOT NULL DEFAULT false,`tool_support` numeric NOT NULL DEFAULT false,`forced_tool_choice` numeric NOT NULL DEFAULT false,`structured_output` numeric NOT NULL DEFAULT false,`honors_max_tokens` numeric NOT NULL,`reasoning_support` numeric NOT NULL DEFAULT false,`reasoning_mode` text NOT NULL DEFAULT "",`reasoning_control` text NOT NULL DEFAULT "",`reasoning_default` numeric NOT NULL DEFAULT false,`reasoning_stream_block` text NOT NULL DEFAULT "",`validation_status` text NOT NULL DEFAULT "",`validation_age_bucket` text NOT NULL DEFAULT "",`eligible` numeric NOT NULL,`selected` numeric NOT NULL,PRIMARY KEY (`request_id`,`candidate_index`),CONSTRAINT `fk_request_usage_decision_candidates` FOREIGN KEY (`request_id`) REFERENCES `request_usage`(`request_id`) ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE `request_target_filter_reasons` (`request_id` text,`seq` integer NOT NULL,`candidate_index` integer NOT NULL,`stage` text NOT NULL,`reason` text NOT NULL,PRIMARY KEY (`request_id`,`seq`),CONSTRAINT `fk_request_usage_decision_filter_reasons` FOREIGN KEY (`request_id`) REFERENCES `request_usage`(`request_id`) ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE `request_token_estimates` (`request_id` text,`ts` text NOT NULL,`inbound_dialect` text NOT NULL,`requested_model` text NOT NULL,`resolved_group` text NOT NULL DEFAULT "",`estimate_method` text NOT NULL DEFAULT "",`estimate_version` text NOT NULL DEFAULT "",`estimated_input_tokens` integer NOT NULL DEFAULT 0,`estimated_tool_schema_tokens` integer NOT NULL DEFAULT 0,`estimated_image_tokens` integer NOT NULL DEFAULT 0,`estimated_audio_tokens` integer NOT NULL DEFAULT 0,`estimated_total_input_tokens` integer NOT NULL DEFAULT 0,`requested_output_cap_tokens` integer NOT NULL DEFAULT 0,`requested_output_cap_field` text NOT NULL DEFAULT "",`router_default_output_cap_applied` numeric NOT NULL DEFAULT false,`total_reserved_tokens` integer NOT NULL DEFAULT 0,`request_bytes` integer NOT NULL DEFAULT 0,`translated_request_bytes` integer NOT NULL DEFAULT 0,`estimate_warning_count` integer NOT NULL DEFAULT 0,`estimate_confidence_bucket` text NOT NULL DEFAULT "",PRIMARY KEY (`request_id`),CONSTRAINT `fk_request_usage_token_estimate` FOREIGN KEY (`request_id`) REFERENCES `request_usage`(`request_id`) ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE `request_trace_events` (`request_id` text,`seq` integer NOT NULL,`ts` text NOT NULL,`event` text NOT NULL,`message` text NOT NULL,`provider` text NOT NULL,`model` text NOT NULL,`dialect` text NOT NULL,`duration_ms` integer NOT NULL,`status_code` integer NOT NULL,`error_class` text NOT NULL,`retryable` numeric NOT NULL,`attempt` integer NOT NULL,PRIMARY KEY (`request_id`,`seq`));
CREATE TABLE `request_traffic_shape_events` (`request_id` text,`seq` integer,`scope` text NOT NULL,`bucket` text NOT NULL,`decision` text NOT NULL,`cost` integer NOT NULL DEFAULT 0,`retry_after_ms` integer NOT NULL DEFAULT 0,`queue_wait_ms` integer NOT NULL DEFAULT 0,`estimated_input_tokens` integer NOT NULL DEFAULT 0,`reserved_output_tokens` integer NOT NULL DEFAULT 0,`total_reserved_tokens` integer NOT NULL DEFAULT 0,PRIMARY KEY (`request_id`,`seq`),CONSTRAINT `fk_request_usage_traffic_shape_events` FOREIGN KEY (`request_id`) REFERENCES `request_usage`(`request_id`) ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE `request_translation_field_events` (`request_id` text,`attempt_index` integer NOT NULL,`seq` integer NOT NULL,`field_name` text NOT NULL,`action` text NOT NULL,`reason` text NOT NULL DEFAULT "",PRIMARY KEY (`request_id`,`attempt_index`,`seq`));
CREATE TABLE `request_translation_shapes` (`request_id` text,`attempt_index` integer NOT NULL,`ts` text NOT NULL,`provider` text NOT NULL,`model` text NOT NULL,`dialect` text NOT NULL,`bridge_direction` text NOT NULL DEFAULT "",`endpoint_path` text NOT NULL DEFAULT "",`translated_stream` numeric NOT NULL DEFAULT false,`translated_tool_count` integer NOT NULL DEFAULT 0,`translated_tool_choice_mode` text NOT NULL DEFAULT "",`translated_output_cap_field` text NOT NULL DEFAULT "",`translated_output_cap_bucket` text NOT NULL DEFAULT "",`translated_reasoning_control` text NOT NULL DEFAULT "",`translated_request_bytes_bucket` text NOT NULL DEFAULT "",`fields_stripped_count` integer NOT NULL DEFAULT 0,`fields_rewritten_count` integer NOT NULL DEFAULT 0,`unsupported_fields_present` numeric NOT NULL DEFAULT false,`translation_warning_count` integer NOT NULL DEFAULT 0,`request_shape_fingerprint` text NOT NULL DEFAULT "",`tool_schema_fingerprint` text NOT NULL DEFAULT "",PRIMARY KEY (`request_id`,`attempt_index`));
CREATE TABLE `request_upstream_error_details` (`request_id` text,`attempt_index` integer NOT NULL,`seq` integer NOT NULL,`ts` text NOT NULL,`status_code` integer NOT NULL,`error_class` text NOT NULL,`field_name` text NOT NULL,`field_value` text NOT NULL,`source` text NOT NULL,`truncated` numeric NOT NULL DEFAULT false,PRIMARY KEY (`request_id`,`attempt_index`,`seq`),CONSTRAINT `fk_request_usage_upstream_error_details` FOREIGN KEY (`request_id`) REFERENCES `request_usage`(`request_id`) ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE `request_upstream_shape_events` (`request_id` text,`seq` integer NOT NULL,`ts` text NOT NULL,`scope` text NOT NULL,`provider` text NOT NULL,`model_ref` text NOT NULL,`model` text NOT NULL,`dialect` text NOT NULL,`bucket` text NOT NULL,`decision` text NOT NULL,`retry_after_ms` integer NOT NULL,`estimated_input_tokens` integer NOT NULL,`reserved_output_tokens` integer NOT NULL,`total_reserved_tokens` integer NOT NULL,`backoff_reason` text NOT NULL,`queue_wait_ms` integer NOT NULL,PRIMARY KEY (`request_id`,`seq`));
CREATE TABLE `request_usage` (`request_id` text,`ts` text NOT NULL,`caller_id` text NOT NULL,`caller_user` text NOT NULL,`caller_project` text NOT NULL,`caller_environment` text NOT NULL,`caller_ip` text,`token_id` text NOT NULL,`client` text NOT NULL,`inbound_dialect` text NOT NULL,`requested_model` text NOT NULL,`resolved_group` text NOT NULL,`strategy` text NOT NULL,`target_provider` text NOT NULL,`target_model` text NOT NULL,`target_dialect` text NOT NULL,`stream` numeric NOT NULL,`cache` text NOT NULL,`status` integer NOT NULL,`attempts` integer NOT NULL,`fallback_used` numeric NOT NULL,`latency_ms` integer NOT NULL,`ttfb_ms` integer,`upstream_duration_ms` integer,`downstream_duration_ms` integer,`upstream_output_tokens_per_sec` real,`upstream_total_tokens_per_sec` real,`downstream_output_tokens_per_sec` real,`downstream_total_tokens_per_sec` real,`input_tokens` integer NOT NULL,`output_tokens` integer NOT NULL,`total_tokens` integer NOT NULL,`input_has_image` numeric NOT NULL DEFAULT false,`input_image_count` integer NOT NULL DEFAULT 0,`input_image_tokens` integer NOT NULL DEFAULT 0,`pii_filter_applied` numeric NOT NULL DEFAULT false,`pii_filter_mode` text NOT NULL DEFAULT "",`pii_filter_replacements` integer NOT NULL DEFAULT 0,`pii_filter_rule_count` integer NOT NULL DEFAULT 0,`contract_present` numeric NOT NULL DEFAULT false,`contract_bucket` text NOT NULL DEFAULT "",`contract_failure_reason` text NOT NULL DEFAULT "",`contract_workload` text NOT NULL DEFAULT "",`target_validation_status` text NOT NULL DEFAULT "",`target_validation_workload` text NOT NULL DEFAULT "",`target_validation_age_bucket` text NOT NULL DEFAULT "",`input_price_per_million_usd` real NOT NULL DEFAULT 0,`output_price_per_million_usd` real NOT NULL DEFAULT 0,`image_input_price_per_million_tokens_usd` real NOT NULL DEFAULT 0,`image_input_price_per_image_usd` real NOT NULL DEFAULT 0,`input_cost_usd` real NOT NULL DEFAULT 0,`image_cost_usd` real NOT NULL DEFAULT 0,`output_cost_usd` real NOT NULL DEFAULT 0,`total_cost_usd` real NOT NULL DEFAULT 0,`upstream_reported_input_cost_usd` real NOT NULL DEFAULT 0,`upstream_reported_output_cost_usd` real NOT NULL DEFAULT 0,`upstream_reported_total_cost_usd` real NOT NULL DEFAULT 0,`pricing_source` text NOT NULL DEFAULT "",`pricing_updated_at` text NOT NULL DEFAULT "",`cache_enabled` numeric NOT NULL,`cache_items` integer NOT NULL,`cache_bytes` integer NOT NULL,`cache_max_bytes` integer NOT NULL,`cache_occupancy_pct` real NOT NULL,`quota_state` text NOT NULL,`key_state` text NOT NULL,`traffic_shape_applied` numeric NOT NULL DEFAULT false,`traffic_shape_decision` text NOT NULL DEFAULT "",`traffic_shape_scope` text NOT NULL DEFAULT "",`traffic_shape_bucket` text NOT NULL DEFAULT "",`traffic_shape_retry_after_ms` integer NOT NULL DEFAULT 0,`traffic_shape_queue_wait_ms` integer NOT NULL DEFAULT 0,`traffic_shape_estimated_input_tokens` integer NOT NULL DEFAULT 0,`traffic_shape_reserved_output_tokens` integer NOT NULL DEFAULT 0,`traffic_shape_total_reserved_tokens` integer NOT NULL DEFAULT 0,`router_version` text NOT NULL DEFAULT "",`router_build_date` text NOT NULL DEFAULT "",`routing_config_fingerprint` text NOT NULL DEFAULT "",`model_group_config_fingerprint` text NOT NULL DEFAULT "",`routing_policy_fingerprint` text NOT NULL DEFAULT "",`pricing_catalog_fingerprint` text NOT NULL DEFAULT "",`error` text NOT NULL, `reasoning_tokens` integer, `reasoning_attempt_count` integer NOT NULL DEFAULT 0, `reasoning_successful_attempt_count` integer NOT NULL DEFAULT 0, `reasoning_reported_attempt_count` integer NOT NULL DEFAULT 0, `target_region` text NOT NULL DEFAULT "", `cached_input_tokens` integer, `cached_input_price_per_million_usd` real, `cost_list_usd` real NOT NULL DEFAULT 0, `cost_billed_usd` real NOT NULL DEFAULT 0, `usage_source` text NOT NULL DEFAULT "", `cache_write_input_tokens` integer, `cache_write_price_per_million_usd` real, `request_kind` text NOT NULL DEFAULT "", `endpoint` text NOT NULL DEFAULT "",PRIMARY KEY (`request_id`));
CREATE TABLE `response_affinity` (`id` integer PRIMARY KEY AUTOINCREMENT,`owner_token_fingerprint` text NOT NULL,`owner_fingerprint_key_id` text NOT NULL,`tenant` text NOT NULL,`project` text NOT NULL,`environment` text NOT NULL,`response_lookup_hash` text NOT NULL,`lookup_hash_key_id` text NOT NULL,`upstream_id_ciphertext` text NOT NULL,`upstream_id_nonce` text NOT NULL,`upstream_id_key_id` text NOT NULL,`provider` text NOT NULL,`account_ref` text NOT NULL,`model` text NOT NULL,`model_group` text NOT NULL,`provider_dialect` text NOT NULL,`endpoint` text NOT NULL,`state` text NOT NULL,`background` numeric NOT NULL DEFAULT false,`usage_settled` numeric NOT NULL DEFAULT false,`settled_at` text NOT NULL,`upstream_delete_state` text NOT NULL,`tombstoned_at` text NOT NULL,`last_error_class` text NOT NULL,`created_at` text NOT NULL,`updated_at` text NOT NULL,`expires_at` text NOT NULL);
CREATE TABLE `retention_job_table_results` (`id` integer PRIMARY KEY AUTOINCREMENT,`job_id` integer NOT NULL,`data_class` text NOT NULL,`table_name` text NOT NULL,`cutoff_ts` text NOT NULL,`retention_days` integer NOT NULL,`batch_size` integer NOT NULL,`candidate_rows` integer NOT NULL DEFAULT 0,`held_rows` integer NOT NULL DEFAULT 0,`eligible_rows` integer NOT NULL DEFAULT 0,`blocked_rows` integer NOT NULL DEFAULT 0,`deleted_rows` integer NOT NULL DEFAULT 0,`status` text NOT NULL,`message` text NOT NULL DEFAULT "",`started_at` text NOT NULL,`completed_at` text NOT NULL,CONSTRAINT `fk_retention_job_table_results_job` FOREIGN KEY (`job_id`) REFERENCES `retention_jobs`(`id`) ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE `retention_jobs` (`id` integer PRIMARY KEY AUTOINCREMENT,`policy_version_id` integer NOT NULL,`mode` text NOT NULL,`status` text NOT NULL,`dry_run` numeric NOT NULL,`started_at` text NOT NULL,`completed_at` text NOT NULL DEFAULT "",`requested_by` text NOT NULL DEFAULT "",`error_message` text NOT NULL DEFAULT "",CONSTRAINT `fk_retention_jobs_policy_version` FOREIGN KEY (`policy_version_id`) REFERENCES `retention_policy_versions`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE `retention_policy_rules` (`id` integer PRIMARY KEY AUTOINCREMENT,`policy_version_id` integer NOT NULL,`rule_order` integer NOT NULL,`data_class` text NOT NULL,`enabled` numeric NOT NULL,`retention_days` integer NOT NULL,`batch_size` integer NOT NULL,`require_finalized_rollup` numeric NOT NULL,`created_at` text NOT NULL,CONSTRAINT `fk_retention_policy_rules_policy_version` FOREIGN KEY (`policy_version_id`) REFERENCES `retention_policy_versions`(`id`) ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE `retention_policy_versions` (`id` integer PRIMARY KEY AUTOINCREMENT,`version` text NOT NULL,`config_hash` text NOT NULL,`source` text NOT NULL,`active` numeric NOT NULL,`dry_run` numeric NOT NULL,`default_batch_size` integer NOT NULL,`created_at` text NOT NULL,`activated_at` text NOT NULL,`deactivated_at` text NOT NULL DEFAULT "",`notes` text NOT NULL DEFAULT "");
CREATE TABLE schema_data_job_checkpoints (job_id TEXT NOT NULL, checkpoint_ordinal BIGINT NOT NULL, shard TEXT NOT NULL DEFAULT '', range_start BIGINT NOT NULL DEFAULT 0, range_end BIGINT NOT NULL DEFAULT 0, cursor TEXT NOT NULL DEFAULT '', rows_scanned BIGINT NOT NULL DEFAULT 0, rows_updated BIGINT NOT NULL DEFAULT 0, rows_skipped BIGINT NOT NULL DEFAULT 0, rows_failed BIGINT NOT NULL DEFAULT 0, state TEXT NOT NULL, started_at TEXT NOT NULL, completed_at TEXT NOT NULL DEFAULT '', PRIMARY KEY (job_id, checkpoint_ordinal), CONSTRAINT schema_data_job_checkpoints_job_fk FOREIGN KEY (job_id) REFERENCES schema_data_jobs(job_id) ON DELETE RESTRICT);
CREATE TABLE schema_data_jobs (job_id TEXT NOT NULL PRIMARY KEY, scope TEXT NOT NULL, migration_id BIGINT NOT NULL, data_version BIGINT NOT NULL, state TEXT NOT NULL, execution_mode TEXT NOT NULL, validation_mode TEXT NOT NULL, throttle_per_minute BIGINT NOT NULL DEFAULT 0, rows_scanned BIGINT NOT NULL DEFAULT 0, rows_updated BIGINT NOT NULL DEFAULT 0, rows_skipped BIGINT NOT NULL DEFAULT 0, rows_failed BIGINT NOT NULL DEFAULT 0, started_at TEXT NOT NULL, completed_at TEXT NOT NULL DEFAULT '', cancel_requested_at TEXT NOT NULL DEFAULT '', safe_error_class TEXT NOT NULL DEFAULT '', CONSTRAINT schema_data_jobs_ledger_fk FOREIGN KEY (scope, migration_id) REFERENCES schema_migration_ledger(scope, migration_id) ON DELETE RESTRICT);
CREATE TABLE schema_migration_attempts (scope TEXT NOT NULL, migration_id BIGINT NOT NULL, attempt BIGINT NOT NULL, action TEXT NOT NULL, state TEXT NOT NULL, owner_generation BIGINT NOT NULL DEFAULT 0, backup_evidence_ref TEXT NOT NULL DEFAULT '', recovery_evidence_ref TEXT NOT NULL DEFAULT '', started_at TEXT NOT NULL, completed_at TEXT NOT NULL DEFAULT '', safe_error_class TEXT NOT NULL DEFAULT '', PRIMARY KEY (scope, migration_id, attempt), CONSTRAINT schema_migration_attempts_ledger_fk FOREIGN KEY (scope, migration_id) REFERENCES schema_migration_ledger(scope, migration_id) ON DELETE RESTRICT);
